const OpenAI = require('openai');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(helmet());
app.use(express.json({ limit: '10kb' }));

const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

// Rate limiting per user
const aiLimiter = rateLimit({
  windowMs: 60 * 1000,
  max: 10,
  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true
});

// Input sanitization for prompt injection patterns
function sanitizeUserInput(input) {
  if (typeof input !== 'string') return '';

  const dangerousPatterns = [
    /ignore\s+(all\s+)?previous\s+instructions/gi,
    /you\s+are\s+now\s+in\s+\w+\s+mode/gi,
    /reveal\s+(the\s+)?system\s+prompt/gi,
    /disregard\s+(all\s+)?prior/gi,
    /forget\s+(everything|all)/gi,
    /\[\s*SYSTEM\s*\]/gi,
    /<\|.*?\|>/g  // Common delimiter injection
  ];

  let sanitized = input.trim().slice(0, 2000);  // Length limit

  for (const pattern of dangerousPatterns) {
    if (pattern.test(sanitized)) {
      console.warn(`Potential prompt injection detected: ${pattern}`);
      sanitized = sanitized.replace(pattern, '[FILTERED]');
    }
  }

  return sanitized;
}

// Output filtering for sensitive content
function filterAIResponse(response) {
  const sensitivePatterns = [
    /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g,  // Emails
    /\b\d{3}-\d{2}-\d{4}\b/g,  // SSN pattern
    /sk-[a-zA-Z0-9]{32,}/g,  // OpenAI API keys
    /\b(?:password|secret|api[_-]?key)\s*[:=]\s*['"][^'"]+['"]/gi
  ];

  let filtered = response;
  for (const pattern of sensitivePatterns) {
    filtered = filtered.replace(pattern, '[REDACTED]');
  }

  return filtered;
}

app.post('/api/chat', aiLimiter, async (req, res) => {
  const requestId = uuidv4();
  const { userMessage } = req.body;

  // Input validation
  const sanitizedInput = sanitizeUserInput(userMessage);
  if (!sanitizedInput || sanitizedInput.length < 2) {
    return res.status(400).json({ error: 'Invalid input' });
  }

  // Static system prompt - never include user data
  const systemPrompt = `You are a helpful customer service assistant.
