	_ "github.com/lib/pq"
)

var db *sql.DB

type TenantContext struct {
	TenantID int
	UserID   int
	Role     string
}

type Customer struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
	// SSN intentionally omitted from response
}

// TenantIsolationMiddleware extracts and validates tenant from JWT
func TenantIsolationMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Extract tenant from validated JWT (not from user input)
		tenantCtx, err := extractTenantFromJWT(r)
		if err != nil {
			log.Printf("SECURITY: Invalid tenant context from %s", r.RemoteAddr)
			http.Error(w, "Unauthorized", http.StatusUnauthorized)
			return
		}

		ctx := context.WithValue(r.Context(), "tenant", tenantCtx)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

// SECURE: Always enforces tenant boundary in query
func getCustomer(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	customerID := vars["id"]

	// Get tenant from authenticated context (NOT user input)
	tenantCtx := r.Context().Value("tenant").(TenantContext)

	// SECURE: Query ALWAYS includes tenant_id condition
	query := `
		SELECT id, name, email 
		FROM customers 
		WHERE id = $1 AND tenant_id = $2
	`
	row := db.QueryRow(query, customerID, tenantCtx.TenantID)

	var customer Customer
	err := row.Scan(&customer.ID, &customer.Name, &customer.Email)
	if err == sql.ErrNoRows {
		// Log potential attack - resource exists but not for this tenant
		log.Printf("SECURITY: Tenant %d attempted access to customer %s",
			tenantCtx.TenantID, customerID)
		http.Error(w, "Customer not found", http.StatusNotFound)
		return
	}
	if err != nil {
		log.Printf("Database error: %v", err)
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}

	json.NewEncoder(w).Encode(customer)
}

// SECURE: Tenant always from authenticated context
func listCustomers(w http.ResponseWriter, r *http.Request) {
	tenantCtx := r.Context().Value("tenant").(TenantContext)

	// Tenant ID NEVER from query params - always from auth context
	query := `
		SELECT id, name, email 
		FROM customers 
		WHERE tenant_id = $1
		ORDER BY id
		LIMIT 100
	`
	rows, err := db.Query(query, tenantCtx.TenantID)
	if err != nil {
		log.Printf("Database error: %v", err)
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	customers := make([]Customer, 0)
	for rows.Next() {
		var c Customer
		if err := rows.Scan(&c.ID, &c.Name, &c.Email); err != nil {
			continue
		}
		customers = append(customers, c)
	}

	json.NewEncoder(w).Encode(customers)
}

func extractTenantFromJWT(r *http.Request) (TenantContext, error) {
	// Implementation validates JWT signature and extracts claims
	// Returns error if token invalid or tenant claim missing
	return TenantContext{TenantID: 1, UserID: 100, Role: "user"}, nil
}

