import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import java.sql.*;
import java.util.logging.Logger;

public class SecurePasswordService {
    private static final Logger logger = Logger.getLogger(SecurePasswordService.class.getName());
    private static final String DB_URL = "jdbc:postgresql://localhost/userdb";
    private static final String DB_USER = "appuser";
    private static final String DB_PASS = "password";

    // BCrypt with strength factor 12 (~250ms per hash)
    private final PasswordEncoder passwordEncoder = new BCryptPasswordEncoder(12);

    public String hashPassword(String password) {
        // SECURE: BCrypt includes automatic salting and configurable work factor
        return passwordEncoder.encode(password);
    }

    public boolean verifyPassword(String rawPassword, String storedHash) {
        // SECURE: Constant-time comparison prevents timing attacks
        return passwordEncoder.matches(rawPassword, storedHash);
    }

    public void registerUser(String username, String password) throws SQLException {
        // Validate password strength before hashing
        if (!isPasswordStrong(password)) {
            throw new IllegalArgumentException("Password does not meet strength requirements");
        }

        String hashedPassword = hashPassword(password);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(
                 "INSERT INTO users (username, password_hash, hash_algorithm) VALUES (?, ?, ?)")) {
            stmt.setString(1, username);
            stmt.setString(2, hashedPassword);
            stmt.setString(3, "bcrypt"); // Track algorithm for future migrations
            stmt.executeUpdate();
            logger.info("User registered successfully: " + username);
        }
    }

    private boolean isPasswordStrong(String password) {
        return password != null && 
               password.length() >= 12 &&
               password.matches(".*[A-Z].*") &&
               password.matches(".*[a-z].*") &&
               password.matches(".*[0-9].*");
    }
}

